    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> tok = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            StringTokenizer st = new StringTokenizer(line);
            while (st.hasMoreTokens()) tok.add(st.nextToken());
        }
        long p = Long.parseLong(tok.get(tok.size() - 2)), q = Long.parseLong(tok.get(tok.size() - 1));
        int m = tok.size() - 2;
        TreeNode root = new TreeNode(Long.parseLong(tok.get(0)));
        Map<Long, TreeNode> nodes = new HashMap<>();
        nodes.put(root.val, root);
        ArrayDeque<TreeNode> queue = new ArrayDeque<>();
        queue.add(root);
        int i = 1;
        while (!queue.isEmpty() && i < m) {
            TreeNode node = queue.poll();
            for (int side = 0; side < 2; side++, i++) {
                if (i < m && !tok.get(i).equals("null")) {
                    TreeNode child = new TreeNode(Long.parseLong(tok.get(i)));
                    nodes.put(child.val, child);
                    if (side == 0) node.left = child; else node.right = child;
                    queue.add(child);
                }
            }
        }
        TreeNode ans = lowestCommonAncestor(root, nodes.get(p), nodes.get(q));
        System.out.println(ans != null ? String.valueOf(ans.val) : "null");
